1	// "`applicationWillTerminate` is not 'every exit path' by itself", as a check.
2	//
3	// NSApplication installs no signal handlers, so a bare SIGTERM (Activity
4	// Monitor's Quit, `killall`), SIGINT (Ctrl-C in a dev terminal) or SIGHUP (that
5	// terminal closing) kills the process with no teardown — leaving the input tap's
6	// IOProc registered on the device, which is what wedges some USB webcam mics
7	// until they are re-plugged (#22). `main.swift` routes those three through
8	// `DispatchSourceSignal` → `NSApp.terminate`, and `signal(sig, SIG_IGN)` must
9	// come *before* `resume()` or a signal landing in the gap still takes the fatal
10	// default.
11	//
12	// Two arms, both keyed on the tree actually installing an audio tap — no tap, no
13	// IOProc to abandon, nothing to enforce:
14	//   1. some file must set up signal sources at all, covering all three signals;
15	//   2. in that file, SIG_IGN must precede the first resume().
16	//
17	// The ordering arm compares first-occurrence offsets rather than parsing scopes:
18	// the two calls sit in one small setup block in this app (a `.map` over the
19	// signal list), and a file that acquired a second, unrelated `resume()` above the
20	// setup would be flagged — a false positive that is cheap to see and cheaper than
21	// missing the real ordering bug, which is invisible at runtime until the one
22	// signal that lands in the gap.
23	//
24	// Dependency-free by design (a local pack must load without the canon mount),
25	// so the finding object is built by hand rather than via the engine helper.
26	
27	const REQUIRED_SIGNALS = ['SIGTERM', 'SIGINT', 'SIGHUP'];
28	
29	const inScope = (f) => f.startsWith('mac/Sources/') && f.endsWith('.swift');
30	
31	const rule = {
32	  id: 'macos-audio/signal-teardown-routing',
33	  severity: 'blocking',
34	  description: 'Catchable termination signals reach applicationWillTerminate, and SIG_IGN precedes resume() (mac/Sources/)',
35	  doc: '.claudinite/local/packs/macos-audio/RULES.md',
36	  why: 'a signal that kills the process outright skips the tap teardown and abandons the IOProc on the microphone — the wedge condition the whole lifecycle is built around',
37	
38	  run(ctx) {
39	    const swift = ctx.files.filter(inScope);
40	    const read = new Map();
41	    for (const file of swift) {
42	      const text = ctx.read(file);
43	      if (text !== null) read.set(file, text);
44	    }
45	
46	    // Only an app that installs an audio tap has an IOProc to abandon.
47	    const tapSite = [...read.entries()].find(([, text]) => /\binstallTap\s*\(/.test(text));
48	    if (!tapSite) return [];
49	
50	    const routing = [...read.entries()]
51	      .filter(([, text]) => /\bmakeSignalSource\s*\(/.test(text));
52	
53	    if (routing.length === 0) {
54	      return [{
55	        rule: rule.id,
56	        severity: rule.severity,
57	        file: tapSite[0],
58	        line: 1,
59	        what: `an audio tap is installed in ${tapSite[0]} but nothing routes termination signals to NSApp.terminate`,
60	        why: rule.why,
61	        fix: 'in `main.swift`, map [SIGTERM, SIGINT, SIGHUP] to `DispatchSource.makeSignalSource(signal:queue:)` handlers that call `NSApp.terminate(nil)`, calling `signal(sig, SIG_IGN)` first and holding the sources in a top-level `let` so they outlive setup',
62	        doc: rule.doc,
63	      }];
64	    }
65	
66	    const out = [];
67	    for (const [file, text] of routing) {
68	      const missing = REQUIRED_SIGNALS.filter((s) => !new RegExp(`\\b${s}\\b`).test(text));
69	      if (missing.length > 0) {
70	        out.push({
71	          rule: rule.id,
72	          severity: rule.severity,
73	          file,
74	          line: text.slice(0, text.search(/\bmakeSignalSource\s*\(/)).split('\n').length,
75	          what: `signal routing in ${file} does not cover ${missing.join(', ')}`,
76	          why: rule.why,
77	          fix: `add ${missing.join(', ')} to the routed set — each of them is fatal by default and leaves the tap installed`,
78	          doc: rule.doc,
79	        });
80	      }
81	
82	      const ignore = text.search(/\bsignal\s*\([^)]*SIG_IGN/);
83	      const resume = text.search(/\.resume\s*\(\s*\)/);
84	      if (resume >= 0 && (ignore < 0 || ignore > resume)) {
85	        out.push({
86	          rule: rule.id,
87	          severity: rule.severity,
88	          file,
89	          line: text.slice(0, resume).split('\n').length,
90	          what: ignore < 0
91	            ? `${file} resumes a signal source without ever calling signal(…, SIG_IGN)`
92	            : `${file} calls signal(…, SIG_IGN) only after resume()`,
93	          why: rule.why,
94	          fix: 'call `signal(sig, SIG_IGN)` before `source.resume()` — until the default action is ignored, a signal arriving in the gap still terminates the process outright',
95	          doc: rule.doc,
96	        });
97	      }
98	    }
99	    return out;
100	  },
101	};
102	
103	export default rule;
104

1	// "Assume no toolchain on the machine that runs it", as a check on the one
2	// mechanical half of it: a script may not probe for a Swift toolchain with
3	// `command -v swift` unless `xcode-select -p` has already gated it.
4	//
5	// The owner's Mac installs the DMG from CI and has no Xcode command line tools.
6	// `command -v swift` reports success there anyway, because `/usr/bin/swift` ships
7	// on every Mac as a *stub*: run it without a developer directory and it does not
8	// fail, it pops the "install the command line tools?" panel — an 8 GB download
9	// prompted at the person diagnosing a dead microphone. The probe is therefore not
10	// a weaker test than `xcode-select -p`, it is a test of something else entirely
11	// (the stub's presence, which is universal). `xcode-select -p` fails cleanly when
12	// no developer directory is configured, so it is the gate; `command -v swift` may
13	// only run behind it, as `mac/scripts/diagnose-mic.sh` does.
14	//
15	// Same-or-earlier, not same-line: the gate has to *precede* the probe, and an
16	// `if xcode-select -p …; then` several lines up is as good as an `&&` on the same
17	// line. Backslash continuations are joined first so a probe split across physical
18	// lines is still read as one command, and reported against its first line.
19	//
20	// `#` comments are stripped before matching, in both directions. The script this
21	// rule was learned on *documents* the trap directly above the gated call — "`command
22	// -v swift` is NOT a usable test" — and the first draft of this check flagged that
23	// sentence (the real-tree fixture is what caught it). A commented-out gate is not a
24	// gate either, so the same stripping runs before the gate is credited.
25	//
26	// Dependency-free by design (a local pack must load without the canon mount),
27	// so the finding object is built by hand rather than via the engine helper.
28	
29	// The probes that ask "is there a swift?" — `\bswift\b` deliberately does not
30	// match `swiftlint`, `swift-format` or any other tool that merely starts that way.
31	const PROBE = /\b(?:command\s+-v|which|type\s+-p|hash)\s+(?:\/usr\/bin\/)?swiftc?\b/;
32	
33	// The gate that actually answers the question, in any of its spellings.
34	const GATE = /\bxcode-select\s+-p\b/;
35	
36	// A `#` comment: at the start of a line, or after whitespace. Leaves `${#var}`
37	// and a `#` glued to a word alone, which is as much shell as this needs to know.
38	const stripComment = (s) => s.replace(/(^|\s)#.*$/, '$1');
39	
40	const inScope = (f) => /\.(?:sh|bash|zsh)$/.test(f)
41	  || (f.startsWith('.github/workflows/') && /\.ya?ml$/.test(f));
42	
43	// Physical lines → logical lines, folding trailing-backslash continuations.
44	// Each entry keeps the 1-based physical line the command started on.
45	const logicalLines = (text) => {
46	  const out = [];
47	  let buffer = null;
48	  const lines = text.split('\n');
49	  for (let i = 0; i < lines.length; i += 1) {
50	    const line = lines[i];
51	    const continued = /\\$/.test(line);
52	    const body = continued ? line.slice(0, -1) : line;
53	    if (buffer === null) buffer = { line: i + 1, text: body };
54	    else buffer.text += ` ${body.trim()}`;
55	    if (!continued) {
56	      out.push(buffer);
57	      buffer = null;
58	    }
59	  }
60	  if (buffer !== null) out.push(buffer);
61	  return out;
62	};
63	
64	const rule = {
65	  id: 'macos-audio/swift-toolchain-gate',
66	  severity: 'blocking',
67	  description: 'A `command -v swift` probe must sit behind an `xcode-select -p` gate (shell scripts, workflows)',
68	  doc: '.claudinite/local/packs/macos-audio/RULES.md',
69	  why: '/usr/bin/swift is a stub that exists on every Mac and prompts an 8 GB command-line-tools install when run without a developer directory, so `command -v swift` passes on the toolchain-less Mac this app is diagnosed on',
70	
71	  run(ctx) {
72	    const out = [];
73	    for (const file of ctx.files.filter(inScope)) {
74	      const text = ctx.read(file);
75	      if (text === null) continue;
76	      let gated = false;
77	      for (const { line, text: raw } of logicalLines(text)) {
78	        const command = stripComment(raw);
79	        if (GATE.test(command)) gated = true;
80	        if (gated || !PROBE.test(command)) continue;
81	        out.push({
82	          rule: rule.id,
83	          severity: rule.severity,
84	          file,
85	          line,
86	          what: `probes for a Swift toolchain with no \`xcode-select -p\` gate before it (${file}:${line})`,
87	          why: rule.why,
88	          fix: 'gate on the developer directory first — `if xcode-select -p >/dev/null 2>&1 && command -v swift >/dev/null 2>&1; then …` — and keep the fallback path working without a toolchain at all, since the Mac that runs this installs the DMG from CI',
89	          doc: rule.doc,
90	        });
91	      }
92	    }
93	    return out;
94	  },
95	};
96	
97	export default rule;
98

